/*
 * A330279  Numbers k such that x^k == k (mod k + 1) has multiple solutions
 *          for 0 <= x < k.
 * https://oeis.org/A330279
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 20, u16 n <= 9743, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   build_primes_upto, gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: odd k such that gcd(k, φ(k+1)) > 1   (multiple solutions for x^k ≡ k (mod k+1)) */

/* The sequence is generated by testing each odd integer k for the
   condition gcd(k, φ(k+1)) > 1.  The Euler totient φ(m) is computed
   using prime factorisation of m, where the list of primes is
   generated once up to a fixed bound (500 000, which comfortably
   covers the range needed for n ≤ 10 000).  The resulting terms are
   cached so that calls to a() in arbitrary order are efficient. */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* Utilities provided by the Build system */
#include "../utils/gcd.h"                /* seq_t gcd(seq_t a, seq_t b) */
#include "../utils/build_primes_upto.h"  /* void build_primes_upto(idx_t limit, uint64_t **out, size_t *cnt) */

static uint64_t *prime_list = NULL;      /* list of primes up to the limit */
static size_t     prime_cnt   = 0;        /* number of primes in the list */

/* initialise the global prime list (once) */
static void init_prime_list(void)
{
    if (!prime_list)
    {
        /* 500 000 is more than enough for n ≤ 10 000 (k < 200 000) */
        build_primes_upto(500000, &prime_list, &prime_cnt);
    }
}

/* Compute φ(m) where m ≤ 2^64-1 using the global prime list.  */
static seq_t totient_uint64(uint64_t m)
{
    seq_t phi = (seq_t)m;
    uint64_t tmp = m;

    for (size_t i = 0; i < prime_cnt; ++i)
    {
        uint64_t p = prime_list[i];
        if (p > tmp / p)          /* p * p > tmp, stop */
            break;
        if (tmp % p == 0)
        {
            while (tmp % p == 0)
                tmp /= p;
            phi = phi / (seq_t)p * (seq_t)(p - 1);
        }
    }
    if (tmp > 1)                  /* remaining prime factor */
        phi = phi / (seq_t)tmp * (seq_t)(tmp - 1);

    return phi;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    if (n == 0)          /* undefined; return 0 for safety */
        return (seq_t)0;

    /* static cache of computed terms */
    static seq_t *cache = NULL;
    static size_t cache_len = 0, cache_cap = 0;

    /* pointer to next odd k to examine */
    static uint64_t next_k = 1;   /* start from k = 1 (will skip to 3 next) */

    init_prime_list();           /* ensure primes available */

    while (cache_len < (size_t)n)
    {
        /* advance to the next odd k */
        if (next_k <= 1)
            next_k = 3;
        else
            next_k += 2;

        seq_t k  = (seq_t)next_k;
        uint64_t m = next_k + 1;          /* m = k + 1 */

        seq_t phi_m = totient_uint64(m);

        seq_t g = gcd(k, phi_m);
        if (g > (seq_t)1)                     /* extra solution exists */
        {
            if (cache_len >= cache_cap)
            {
                size_t new_cap = cache_cap ? cache_cap * 2 : 16;
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!tmp) /* allocation failure; abort */
                    exit(EXIT_FAILURE);
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = k;
        }
    }

    return cache[n - 1];
}
